import { getBeatsPerMeasure } from 'app/services/MelodiesService/meter';
import { DEFAULT_BPM } from 'app/services/MelodiesService/timing';
import type { Melody, NoteInMelody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { getNote, splitNote } from 'app/services/NotesService/noteUtils';
import type { Octave } from 'app/services/NotesService/types';

import { type FretPosition, MAX_FRET } from './fingering';
import type { TabNote } from './tabCreator';
import { tabExpression } from './tabPlayback';
import { STRINGS, type StringInstrumentType } from './tuning';

type Cell = { index: number; note: TabNote };
export type StudioTabStep = {
  id: string;
  tick: number;
  start: number;
  cells: (Cell | null)[];
};

export const tabMeter = (melody: Melody) => ({
  eighth: 30000 / (melody.bpm ?? DEFAULT_BPM),
  stepsPerBar: 2 * getBeatsPerMeasure(melody.timeSignature),
});

// Eliminate rounding noise from tempo changes without quantizing performances.
const tickAt = (start: number, eighth: number) =>
  Math.round((start / eighth) * 1e7) / 1e7;

export const tabBarAt = (melody: Melody, start: number) => {
  const { eighth, stepsPerBar } = tabMeter(melody);
  return Math.floor(tickAt(start, eighth) / stepsPerBar);
};

const toCell = (
  { expression }: NoteInMelody,
  { fret }: FretPosition,
): TabNote => {
  const kinds = expression?.techniques ?? [];
  const points = expression?.points ?? [];
  const peak = points.reduce(
    (best, point) =>
      Math.abs(point.cents) > Math.abs(best) ? point.cents : best,
    0,
  );
  const end = points[points.length - 1]?.cents ?? 0;
  const slide = Math.max(
    0,
    Math.min(
      MAX_FRET,
      fret + (Math.round(end / 100) || Math.round(peak / 100)),
    ),
  );
  const hasSlide = kinds.includes('slide') && slide !== fret;
  return {
    fret,
    slide: hasSlide ? slide : undefined,
    bend:
      !hasSlide && kinds.includes('bend')
        ? Math.max(1, Math.min(3, Math.round(Math.abs(peak) / 100)))
        : undefined,
    vibrato: kinds.includes('vibrato') || kinds.includes('wide-vibrato'),
    expression,
  };
};

export const studioTabBar = (
  melody: Melody,
  positions: readonly (FretPosition | undefined)[],
  instrument: StringInstrumentType,
  bar: number,
  selectedTick?: number,
) => {
  const { eighth, stepsPerBar } = tabMeter(melody);
  const first = bar * stepsPerBar;
  const groups = new Map<number, StudioTabStep[]>();
  const append = (tick: number, start: number) => {
    const group = groups.get(tick) ?? [];
    const step = {
      id: `${tick}:${group.length}`,
      tick,
      start,
      cells: Array<Cell | null>(STRINGS[instrument].length).fill(null),
    };
    group.push(step);
    groups.set(tick, group);
    return step;
  };

  for (let i = 0; i < stepsPerBar; i++) append(first + i, (first + i) * eighth);
  if (
    selectedTick !== undefined &&
    selectedTick >= first &&
    selectedTick < first + stepsPerBar &&
    !groups.has(selectedTick)
  )
    append(selectedTick, selectedTick * eighth);

  let unmapped = 0;
  melody.notes.forEach((event, index) => {
    const tick = tickAt(event.start, eighth);
    if (tick < first || tick >= first + stepsPerBar) return;
    const position = positions[index];
    if (!position) {
      unmapped++;
      return;
    }
    // If an imported chord has more than one note on a string, keep all its
    // notes available in adjacent columns at the same time.
    const step =
      groups.get(tick)?.find(({ cells }) => !cells[position.string]) ??
      append(tick, event.start);
    if (!step.cells.some(Boolean)) step.start = event.start;
    step.cells[position.string] = { index, note: toCell(event, position) };
  });
  return {
    steps: Array.from(groups)
      .sort(([a], [b]) => a - b)
      .flatMap(([, steps]) => steps),
    unmapped,
  };
};

export const writeStudioTab = (
  melody: Melody,
  instrument: StringInstrumentType,
  step: StudioTabStep,
  string: number,
  fret: number | null,
  technique?: TabNote,
): NoteInMelody[] => {
  const cell = step.cells[string];
  if (fret === null)
    return cell
      ? melody.notes.filter((_, index) => index !== cell.index)
      : melody.notes;
  if (cell?.note.fret === fret && !technique) return melody.notes;

  const original = cell && melody.notes[cell.index];
  const [open, octave] = splitNote(STRINGS[instrument][string]);
  const offset = chromaticNotes.indexOf(open) + fret;
  const note = getNote(
    chromaticNotes[offset % 12],
    (octave + Math.floor(offset / 12)) as Octave,
  );
  const duration = original?.duration ?? tabMeter(melody).eighth;
  const editedTechnique =
    technique ??
    (cell?.note.slide !== undefined
      ? {
          ...cell.note,
          fret,
          slide: cell.note.slide === fret ? undefined : cell.note.slide,
        }
      : undefined);
  const next: NoteInMelody = {
    ...original,
    note,
    start: original?.start ?? step.start,
    duration,
    expression: editedTechnique
      ? tabExpression(editedTechnique, duration)
      : original?.expression,
    tablature: {
      ...(original?.note === note ? original.tablature : {}),
      [instrument]: { string, fret },
    },
  };
  if (cell)
    return melody.notes.map((event, index) =>
      index === cell.index ? next : event,
    );
  const before = melody.notes.findIndex(event => event.start > step.start);
  return before === -1
    ? [...melody.notes, next]
    : [...melody.notes.slice(0, before), next, ...melody.notes.slice(before)];
};
