import type { RealtimeNote } from 'app/services/GuitarInputService/realtime';
import type { NoteInMelody } from 'app/services/MelodiesService/types';

import { readPreferences, writePreferences } from 'utils/preferences';

import { MAX_FRET, getFretPositions } from './fingering';
import { GuitarTuning, TabEditor, TabNote, emptyStep } from './tabCreator';

const TECHNIQUES_KEY = 'qwertophone.tab-creator.techniques.v1';

export const loadDetectTechniques = () => {
  const { enabled, bend, slide, vibrato } = readPreferences(TECHNIQUES_KEY);
  // Preserve an opt-out from the earlier per-technique settings.
  return typeof enabled === 'boolean'
    ? enabled
    : bend !== false && slide !== false && vibrato !== false;
};

export const saveDetectTechniques = (enabled: boolean) =>
  writePreferences(TECHNIQUES_KEY, { enabled });

const guitarTabNote = (
  { note, duration, expression }: NoteInMelody,
  tuning: GuitarTuning,
) => {
  const positions = getFretPositions(note, tuning).sort(
    (a, b) => a.fret - b.fret,
  );
  if (!positions.length) return;

  const techniques = expression?.techniques ?? [];
  const points = expression?.points ?? [];
  const peak = points.reduce(
    (offset, point) =>
      Math.abs(point.cents) > Math.abs(offset) ? point.cents : offset,
    0,
  );
  const end = points[points.length - 1]?.cents ?? 0;
  // A descending sweep from the unbent pitch is closer to a slide in tabs.
  const slideBy = techniques.includes('slide')
    ? Math.round(end / 100) || Math.round(peak / 100)
    : techniques.includes('bend') && peak <= -50
    ? -Math.round(-peak / 100)
    : 0;
  const { fret, string } =
    positions.find(
      pos => pos.fret + slideBy >= 0 && pos.fret + slideBy <= MAX_FRET,
    ) ?? positions[0];
  const target = Math.max(0, Math.min(MAX_FRET, fret + slideBy));
  const cell: TabNote = {
    fret,
    ...(target !== fret ? { slide: target } : {}),
    ...(!slideBy && techniques.includes('bend')
      ? { bend: Math.max(1, Math.min(3, Math.round(peak / 100))) }
      : {}),
    ...(techniques.includes('vibrato') || techniques.includes('wide-vibrato')
      ? { vibrato: true }
      : {}),
    ...(duration !== undefined && Number.isFinite(duration) && duration > 0
      ? { duration }
      : {}),
    ...(expression ? { expression } : {}),
  };
  return { string, cell };
};

// The monophonic stream emits the final update of a voice before its next
// attack. Only a new ID can claim a step, including after the cursor advances.
export const applyGuitarEvent = (
  editor: TabEditor,
  { id, note }: RealtimeNote,
  detectTechniques: boolean,
): TabEditor => {
  const { draft, cursor, attack } = editor;
  if (attack && id < attack.id) return editor;
  const existing = attack?.id === id ? attack : undefined;
  if (existing && !existing.cell) return editor;
  const position = guitarTabNote(
    detectTechniques ? note : { ...note, expression: undefined },
    draft.tuning,
  );
  if (!position) return existing ? editor : { ...editor, attack: { id } };

  const { string, cell } = position;
  const steps = [...draft.steps];
  let step = existing?.cell?.step ?? cursor.step;
  if (existing?.cell) {
    const notes = [...steps[step]];
    notes[existing.cell.string] = null;
    notes[string] = cell;
    steps[step] = notes;
  } else {
    while (steps[step]?.some(Boolean)) step++;
    const notes = emptyStep();
    notes[string] = cell;
    steps[step] = notes;
    if (step + 1 === steps.length) steps.push(emptyStep());
  }
  return {
    draft: { ...draft, steps },
    cursor: { step: step + 1, string },
    attack: { id, cell: { step, string } },
  };
};
