import { DRUM_TRACKS } from 'app/services/DrumMachineService/patterns';
import { getBeatsPerMeasure } from 'app/services/MelodiesService/meter';
import {
  METRONOME_METERS,
  getMeterBeats,
} from 'app/services/MetronomeService/rhythm';

import type { PhraseNote } from './compose';
import {
  GenerationSettings,
  RHYTHM_TEMPLATE_STEPS,
  STEPS_PER_BEAT,
  rhythms,
} from './options';

const [{ note: kick }, { note: snare }, { note: hat }] = DRUM_TRACKS;

export const fitToBar = (onsets: number[], barSteps: number) =>
  Array.from(
    { length: Math.ceil(barSteps / RHYTHM_TEMPLATE_STEPS) },
    (_, repeat) => onsets.map(start => start + repeat * RHYTHM_TEMPLATE_STEPS),
  )
    .flat()
    .filter(start => start < barSteps);

export const phraseArrangement = ({
  timeSignature,
  rhythm,
  chordPattern,
  drums,
}: GenerationSettings) => {
  const barSteps = getBeatsPerMeasure(timeSignature) * STEPS_PER_BEAT;
  const meter = METRONOME_METERS[timeSignature];
  const beatSteps = (STEPS_PER_BEAT * 4) / meter.unit;
  const beats = getMeterBeats(timeSignature);
  const pulses = beats.map((_, i) => i * beatSteps);
  const subdivisions = pulses.flatMap(start => [start, start + beatSteps / 2]);
  const backbeats =
    meter.groups.length > 1 ? beats.filter(beat => beat.accent) : beats;
  const groove = drums
    ? [
        ...subdivisions.map(start => ({
          midi: hat,
          start,
          length: beatSteps / 2,
        })),
        ...backbeats.map(({ number }, i) => {
          const isKick =
            i === 0 ||
            (i === 2 && (meter.groups.length > 1 || beats.length === 4));
          return {
            midi: isKick ? kick : snare,
            start: pulses[number - 1],
            length: beatSteps,
          };
        }),
      ]
    : [];

  const followed = rhythms[rhythm];
  const chordOnsets = {
    none: [],
    follow: fitToBar(followed.backing, barSteps),
    held: [0],
    beats: pulses,
    offbeats: pulses.map(start => start + beatSteps / 2),
    arpeggio: subdivisions,
  }[chordPattern];

  const chordNotes = (
    chord: number[],
    offset: number,
    final: boolean,
  ): PhraseNote[] => {
    const held =
      chordPattern === 'held' ||
      (chordPattern === 'follow' &&
        (final || (chordOnsets.length === 1 && chordOnsets[0] === 0)));
    const arpeggio =
      !held &&
      (chordPattern === 'arpeggio' ||
        (chordPattern === 'follow' && followed.brokenChord));
    const onsets = held ? [0] : chordOnsets;
    return onsets.flatMap((onset, i) => {
      const pitches = arpeggio ? [chord[i % chord.length]] : chord;
      const span = (onsets[i + 1] ?? barSteps) - onset;
      const length = held || arpeggio ? span : Math.min(span, beatSteps / 2);
      return pitches.map(midi => ({ midi, start: offset + onset, length }));
    });
  };
  return { barSteps, beatSteps, groove, chordNotes };
};
