import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import type { Note } from 'app/services/NotesService/types';

import { Chord, ChordQuality, chordTones, pitchClass } from '.';

// Physical sounding pitches, from the sixth (thickest) to the first string.
export const GUITAR_TUNING: readonly Note[] = [
  'E2',
  'A2',
  'D3',
  'G3',
  'B3',
  'E4',
];
export const MAX_GUITAR_FRET = 15;
export type GuitarBarre = { fret: number; from: number; to: number };
export type GuitarFingering = {
  frets: number[]; // -1: muted, 0: open. Sixth string first.
  fingers: number[]; // 0 for an open or muted string; otherwise 1–4.
  barre?: GuitarBarre;
  notes: Note[];
  firstFret: number;
};

type Shape = { root: string; quality: ChordQuality; frets: number[] };
const shape = (
  root: string,
  quality: ChordQuality,
  frets: number[],
): Shape => ({ root, quality, frets });
// These familiar open shapes also provide movable forms when every sounding
// string is shifted together. Every candidate is validated against the chord.
export const GUITAR_SHAPES: readonly Shape[] = [
  shape('C', 'major', [-1, 3, 2, 0, 1, 0]),
  shape('C', 'major', [0, 3, 2, 0, 1, 0]),
  shape('C', 'major', [3, 3, 2, 0, 1, 0]),
  shape('A', 'major', [-1, 0, 2, 2, 2, 0]),
  shape('G', 'major', [3, 2, 0, 0, 0, 3]),
  shape('E', 'major', [0, 2, 2, 1, 0, 0]),
  shape('D', 'major', [-1, -1, 0, 2, 3, 2]),
  shape('A', 'minor', [-1, 0, 2, 2, 1, 0]),
  shape('E', 'minor', [0, 2, 2, 0, 0, 0]),
  shape('D', 'minor', [-1, -1, 0, 2, 3, 1]),
  shape('C', 'dominant7', [-1, 3, 5, 3, 5, 3]),
  shape('A', 'dominant7', [-1, 0, 2, 0, 2, 0]),
  shape('G', 'dominant7', [3, 2, 0, 0, 0, 1]),
  shape('E', 'dominant7', [0, 2, 0, 1, 0, 0]),
  shape('D', 'dominant7', [-1, -1, 0, 2, 1, 2]),
  shape('B', 'dominant7', [-1, 2, 1, 2, 0, 2]),
  shape('C', 'major7', [-1, 3, 2, 0, 0, 0]),
  shape('A', 'major7', [-1, 0, 2, 1, 2, 0]),
  shape('G', 'major7', [3, 2, 0, 0, 0, 2]),
  shape('E', 'major7', [0, 2, 1, 1, 0, 0]),
  shape('D', 'major7', [-1, -1, 0, 2, 2, 2]),
  shape('A', 'minor7', [-1, 0, 2, 0, 1, 0]),
  shape('E', 'minor7', [0, 2, 0, 0, 0, 0]),
  shape('D', 'minor7', [-1, -1, 0, 2, 1, 1]),
  shape('C', 'diminished', [-1, 3, 4, 5, 4, -1]),
  shape('D', 'diminished', [-1, -1, 0, 1, 3, 1]),
  shape('A', 'diminished', [-1, 0, 1, 2, 1, -1]),
  shape('C', 'augmented', [-1, 3, 2, 1, 1, 0]),
  shape('E', 'augmented', [0, 3, 2, 1, 1, 0]),
  shape('D', 'augmented', [-1, -1, 0, 3, 3, 2]),
  shape('C', 'sus2', [-1, 3, 0, 0, 1, 3]),
  shape('A', 'sus2', [-1, 0, 2, 2, 0, 0]),
  shape('G', 'sus2', [3, 0, 0, 0, 3, 3]),
  shape('E', 'sus2', [0, 2, 4, 4, 0, 0]),
  shape('D', 'sus2', [-1, -1, 0, 2, 3, 0]),
  shape('C', 'sus4', [-1, 3, 3, 0, 1, 1]),
  shape('A', 'sus4', [-1, 0, 2, 2, 3, 0]),
  shape('G', 'sus4', [3, 3, 0, 0, 1, 3]),
  shape('E', 'sus4', [0, 2, 2, 2, 0, 0]),
  shape('D', 'sus4', [-1, -1, 0, 2, 3, 3]),
];

const absolute = (note: Note) => Number(note.slice(-1)) * 12 + pitchClass(note);
const tuning = GUITAR_TUNING.map(absolute);
const noteAt = (string: number, fret: number): Note => {
  const pitch = tuning[string] + fret;
  return `${chromaticNotes[pitch % 12]}${Math.floor(pitch / 12)}` as Note;
};

export const guitarNotes = (frets: readonly number[]): Note[] =>
  frets.flatMap((fret, string) => (fret < 0 ? [] : [noteAt(string, fret)]));

// One index-finger barre is allowed. It may pass underneath higher frets but
// cannot cross an open/muted string. Other fretted notes use separate fingers.
export const guitarFingers = (
  frets: readonly number[],
): Pick<GuitarFingering, 'fingers' | 'barre'> | null => {
  const pressed = frets
    .map((fret, string) => ({ fret, string }))
    .filter(point => point.fret > 0)
    .sort((a, b) => a.fret - b.fret || a.string - b.string);
  if (!pressed.length) return { fingers: Array(6).fill(0) };
  const plans: { fingers: number[]; barre?: GuitarBarre; cost: number }[] = [];
  const assign = (remaining: typeof pressed, barre?: GuitarBarre) => {
    if (remaining.length + (barre ? 1 : 0) > 4) return;
    const fingers = Array(6).fill(0);
    if (barre)
      frets.forEach((fret, string) => {
        if (string >= barre.from && string <= barre.to && fret === barre.fret)
          fingers[string] = 1;
      });
    remaining.forEach((point, index) => {
      fingers[point.string] = index + (barre ? 2 : 1);
    });
    plans.push({ fingers, barre, cost: remaining.length + (barre ? 1.6 : 0) });
  };
  assign(pressed);
  const lowest = pressed[0].fret;
  const atLowest = pressed.filter(point => point.fret === lowest);
  atLowest.forEach((start, index) =>
    atLowest.slice(index + 1).forEach(end => {
      if (
        frets.slice(start.string, end.string + 1).every(fret => fret >= lowest)
      ) {
        const barre = { fret: lowest, from: start.string, to: end.string };
        assign(
          pressed.filter(
            point =>
              point.fret !== lowest ||
              point.string < barre.from ||
              point.string > barre.to,
          ),
          barre,
        );
      }
    }),
  );
  const best = plans.sort((a, b) => a.cost - b.cost)[0];
  return best ? { fingers: best.fingers, barre: best.barre } : null;
};

export const guitarFretCode = (frets: readonly number[]) =>
  frets.map(fret => (fret < 0 ? '×' : String(fret))).join(' · ');

const cache = new Map<string, GuitarFingering[]>();

export const guitarFingerings = (
  chord: Chord,
  inversion = 0,
): GuitarFingering[] => {
  const tones = chordTones(chord);
  const bass = pitchClass(
    tones[Math.max(0, Math.min(tones.length - 1, Math.trunc(inversion)))],
  );
  const key = `${pitchClass(chord.root)}-${chord.quality}-${bass}`;
  const saved = cache.get(key);
  if (saved) return saved;
  const required = tones.map(pitchClass);
  const candidates = new Map<
    string,
    { fingering: GuitarFingering; score: number }
  >();
  const add = (frets: number[], priority: number) => {
    if (frets.some(fret => fret > MAX_GUITAR_FRET || fret < -1)) return;
    const notes = guitarNotes(frets);
    if (notes.length < required.length) return;
    const pitches = notes.map(absolute);
    // Keep the audible bass on the lowest played string.
    if (pitches.some((pitch, index) => index > 0 && pitch < pitches[index - 1]))
      return;
    if (pitches[0] % 12 !== bass) return;
    const classes = Array.from(new Set(pitches.map(pitch => pitch % 12)));
    if (
      classes.length !== required.length ||
      !required.every(pitch => classes.includes(pitch))
    )
      return;
    const positive = frets.filter(fret => fret > 0);
    const first = positive.length ? Math.min(...positive) : 1;
    const last = positive.length ? Math.max(...positive) : 0;
    if (last - first > 3) return;
    const fingers = guitarFingers(frets);
    if (!fingers) return;
    const code = frets.join(',');
    const score =
      priority * 100 +
      first * 2 +
      (last - first) +
      Math.max(...fingers.fingers) +
      (fingers.barre ? 2 : 0) +
      (6 - notes.length) * 0.3;
    if ((candidates.get(code)?.score ?? Infinity) <= score) return;
    candidates.set(code, {
      score,
      fingering: { frets, ...fingers, notes, firstFret: last <= 4 ? 1 : first },
    });
  };

  GUITAR_SHAPES.filter(item => item.quality === chord.quality).forEach(item => {
    const shift = (pitchClass(chord.root) - pitchClass(item.root) + 12) % 12;
    const moved = item.frets.map(fret => (fret < 0 ? -1 : fret + shift));
    add(moved, shift === 0 ? 0 : 1);
    for (let string = 0; string < 4; string++)
      add(
        moved.map((fret, index) => (index <= string ? -1 : fret)),
        2,
      );
  });

  // Search compact contiguous string groups inside four-fret hand positions.
  // Open strings may be retained when they belong to the full chord.
  for (let firstFret = 1; firstFret <= 12; firstFret++) {
    const available = tuning.map(open =>
      [0, firstFret, firstFret + 1, firstFret + 2, firstFret + 3].filter(fret =>
        required.includes((open + fret) % 12),
      ),
    );
    for (let low = 0; low <= 6 - required.length; low++) {
      for (let high = low + required.length - 1; high < 6; high++) {
        const frets = Array(6).fill(-1);
        const visit = (string: number) => {
          if (string > high) {
            add([...frets], 3);
            return;
          }
          available[string].forEach(fret => {
            if (string === low && (tuning[string] + fret) % 12 !== bass) return;
            if (
              string > low &&
              tuning[string] + fret < tuning[string - 1] + frets[string - 1]
            )
              return;
            frets[string] = fret;
            visit(string + 1);
          });
        };
        visit(low);
      }
    }
  }
  const result = Array.from(candidates.values())
    .sort(
      (a, b) =>
        a.score - b.score ||
        a.fingering.frets.join(',').localeCompare(b.fingering.frets.join(',')),
    )
    .slice(0, 8)
    .map(candidate => candidate.fingering);
  cache.set(key, result);
  return result;
};
