import { useEffect, useMemo, useState } from 'react';
import styled from 'styled-components';

import {
  Chord,
  chordSymbol,
  chordTones,
  formatPitch,
} from 'app/services/ChordsService';
import {
  GUITAR_TUNING,
  GuitarFingering,
  guitarFingerings,
  guitarFretCode,
} from 'app/services/ChordsService/guitar';
import type { Note } from 'app/services/NotesService/types';

export const GuitarFingerings = ({
  chord,
  inversion,
  onPlay,
  onStop,
  unpitched,
}: {
  chord: Chord;
  inversion: number;
  onPlay: (notes: Note[]) => void;
  onStop: () => void;
  unpitched: boolean;
}) => {
  const { root, quality } = chord;
  const chordKey = `${root}-${quality}-${inversion}`;
  const [selection, setSelection] = useState({ key: chordKey, index: 0 });
  const fingerings = useMemo(
    () => guitarFingerings({ root, quality }, inversion),
    [root, quality, inversion],
  );
  const index = selection.key === chordKey ? selection.index : 0;
  const fingering = fingerings[index];
  const bass = chordTones(chord)[inversion];
  const symbol = `${chordSymbol(chord)}${
    inversion ? `/${formatPitch(bass)}` : ''
  }`;

  useEffect(() => () => onStop(), [chordKey, onStop]);

  const change = (next: number) => {
    onStop();
    setSelection({ key: chordKey, index: next });
  };

  return (
    <Section id="guitar-fingerings" aria-label="Guitar fingerings">
      <Header>
        <div>
          <h2>Guitar fingerings</h2>
          <Muted>Standard tuning · E–A–D–G–B–E</Muted>
        </div>
        <VariantNavigation aria-label="Fingering options">
          <ArrowButton
            type="button"
            aria-label="Previous fingering"
            disabled={index === 0}
            onClick={() => change(index - 1)}
          >
            ←
          </ArrowButton>
          <span aria-live="polite">
            {fingerings.length
              ? `${index + 1} of ${fingerings.length}`
              : 'No options'}
          </span>
          <ArrowButton
            type="button"
            aria-label="Next fingering"
            disabled={index >= fingerings.length - 1}
            onClick={() => change(index + 1)}
          >
            →
          </ArrowButton>
        </VariantNavigation>
      </Header>
      {fingering ? (
        <Body>
          <DiagramWrap>
            <ChordName>{symbol}</ChordName>
            <FretDiagram fingering={fingering} symbol={symbol} />
            <Muted>6th string on the left · 1st on the right</Muted>
          </DiagramWrap>
          <Details>
            <h3>
              {fingering.frets.includes(0)
                ? 'Open strings'
                : `Position from fret ${fingering.firstFret}`}
            </h3>
            <Muted>
              {fingering.barre
                ? `Barre at fret ${fingering.barre.fret}: strings ${
                    6 - fingering.barre.from
                  }–${6 - fingering.barre.to}.`
                : 'No barre.'}{' '}
              Bass: {formatPitch(fingering.notes[0])}.
            </Muted>
            <StringTable aria-label="Frets and fingers by string">
              <thead>
                <tr>
                  <th scope="col">String</th>
                  {GUITAR_TUNING.map((note, string) => (
                    <th key={string} scope="col">
                      {6 - string}
                      <small>{note.replace(/\d/, '')}</small>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr>
                  <th scope="row">Fret</th>
                  {fingering.frets.map((fret, string) => (
                    <td key={string}>{fret < 0 ? '×' : fret}</td>
                  ))}
                </tr>
                <tr>
                  <th scope="row">Finger</th>
                  {fingering.fingers.map((finger, string) => (
                    <td key={string}>{finger || '·'}</td>
                  ))}
                </tr>
              </tbody>
            </StringTable>
            <Muted aria-label="Fingering code">
              {guitarFretCode(fingering.frets)}
            </Muted>
            <SoundingNotes aria-label="Fingering notes">
              {fingering.notes.map(formatPitch).join(' · ')}
            </SoundingNotes>
            <PlayButton
              type="button"
              disabled={unpitched}
              onClick={() => onPlay(fingering.notes)}
            >
              Preview fingering
            </PlayButton>
            <Muted>
              {unpitched
                ? 'Choose a melodic instrument in the toolbar to preview.'
                : "Plays the shown voicing in the guitar's register with the current instrument and effects."}
            </Muted>
            <Legend>
              × = do not play · ○ = open string
              <br />
              Fingers: 1 = index, 2 = middle, 3 = ring, 4 = little finger.
            </Legend>
          </Details>
        </Body>
      ) : (
        <Muted>
          Try a different inversion. This one has no four-finger shape within
          the first 15 frets.
        </Muted>
      )}
    </Section>
  );
};

const FretDiagram = ({
  fingering,
  symbol,
}: {
  fingering: GuitarFingering;
  symbol: string;
}) => {
  const { frets, fingers, barre, firstFret } = fingering;
  const x = (string: number) => 46 + string * 30;
  const y = (fret: number) => 72 + (fret - firstFret) * 40;
  return (
    <Diagram
      viewBox="0 0 244 260"
      role="img"
      aria-label={`Fingering ${symbol}: ${guitarFretCode(frets)}`}
    >
      <desc>
        Strings run from the sixth on the left to the first on the right. A
        cross means a muted string; a circle means an open string. Numbers
        inside dots indicate fingers.
      </desc>
      {[0, 1, 2, 3, 4].map(fret => (
        <line
          key={`fret-${fret}`}
          x1={x(0)}
          x2={x(5)}
          y1={52 + fret * 40}
          y2={52 + fret * 40}
          className={fret === 0 && firstFret === 1 ? 'nut' : 'fret'}
        />
      ))}
      {frets.map((fret, string) => (
        <g key={string}>
          <line
            x1={x(string)}
            x2={x(string)}
            y1="52"
            y2="212"
            className="string"
            strokeWidth={2.2 - string * 0.2}
          />
          <text x={x(string)} y="30" className="open">
            {fret < 0 ? '×' : fret === 0 ? '○' : ''}
          </text>
          <text x={x(string)} y="236" className="string-name">
            {['E', 'A', 'D', 'G', 'B', 'e'][string]}
          </text>
        </g>
      ))}
      {[0, 1, 2, 3].map(row => (
        <text key={row} x="22" y={77 + row * 40} className="fret-number">
          {firstFret + row}
        </text>
      ))}
      {barre && (
        <line
          x1={x(barre.from)}
          x2={x(barre.to)}
          y1={y(barre.fret)}
          y2={y(barre.fret)}
          className="barre"
        />
      )}
      {frets.map(
        (fret, string) =>
          fret > 0 && (
            <g key={`finger-${string}`}>
              <circle cx={x(string)} cy={y(fret)} r="11" className="finger" />
              <text x={x(string)} y={y(fret) + 4} className="finger-number">
                {fingers[string]}
              </text>
            </g>
          ),
      )}
    </Diagram>
  );
};

