type BooleanDict = Record<string, boolean>;
type ToClassName = (
  classNameOrObject: BooleanDict | string,
  object?: BooleanDict,
) => string;

export const toClassName: ToClassName = (a, b) => {
  const object = (typeof a === 'string' ? b : a) ?? {};
  const basicClassName = typeof a === 'string' ? `${a} ` : '';
  return (
    basicClassName +
    Object.keys(object)
      .filter(c => object[c])
      .join(' ')
  );
};
