import { useEffect, useMemo, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { selectMelodies } from 'app/services/MelodiesService';
import { DEFAULT_BPM } from 'app/services/MelodiesService/timing';

import { useRecordingPlayback } from 'app/components/RecordingPlayback';
import {
  liveScoreHint,
  useRecordingScore,
} from 'app/components/useRecordingScore';

import { StaffLine } from './StaffLine';
import { layoutStaff } from './layout';
import { getLiveStaffPreview } from './livePreview';
import { playbackX } from './playback';

export const Staff = () => {
  const { melody, isRecording, skipped, now } = useRecordingScore(true);
  const playback = useRecordingPlayback();
  const { soundingNoteIndices } = useSelector(selectMelodies);
  const wrapper = useRef<HTMLDivElement>(null);
  const lastLine = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(900);
  const bpm = melody.bpm ?? DEFAULT_BPM;
  const preview = useMemo(
    () => (isRecording ? getLiveStaffPreview(melody, bpm) : undefined),
    [isRecording, melody, bpm],
  );
  const displayNow = preview ? Math.min(now, preview.end) : now;
  const lines = useMemo(
    () =>
      layoutStaff(preview?.melody ?? melody, bpm, displayNow, width, preview),
    [preview, melody, bpm, displayNow, width],
  );
  const activeLine = playback?.timelinePlaying
    ? lines.findIndex(line => playbackX(line, playback.position) !== undefined)
    : -1;
  const following = !!playback?.isPlaying && !playback.isAudition;

  useEffect(() => {
    const element = wrapper.current;
    if (!element) return;
    const measure = () => {
      const measured = Math.floor(element.getBoundingClientRect().width);
      if (measured > 0) setWidth(measured);
    };
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? undefined
        : new ResizeObserver(measure);
    observer?.observe(element);
    window.addEventListener('resize', measure);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, []);
  useEffect(() => {
    if (isRecording) lastLine.current?.scrollIntoView?.({ block: 'center' });
  }, [lines.length, isRecording]);

  useEffect(() => {
    if (following)
      wrapper.current
        ?.querySelector('[data-playback-active="true"]')
        ?.scrollIntoView?.({ block: 'nearest', inline: 'nearest' });
  }, [activeLine, following]);

  return (
    <StaffWrapper ref={wrapper}>
      {isRecording && (skipped > 0 || preview?.omittedNotes) && (
        <small>{liveScoreHint}</small>
      )}
      {lines.map((line, index) => (
        <div
          key={index}
          ref={index === lines.length - 1 ? lastLine : undefined}
          data-playback-active={index === activeLine}
        >
          <StaffLine
            line={line}
            bpm={bpm}
            position={playback?.timelinePlaying ? playback.position : undefined}
            soundingNoteIndices={playback ? soundingNoteIndices : []}
            onSeek={playback?.seek}
          />
        </div>
      ))}
    </StaffWrapper>
  );
};

const StaffWrapper = styled.div`
  min-width: 0;
  width: 100%;
  color: ${p => p.theme.text};
  --staff-background: ${p => p.theme.background};
  --staff-playback: ${p => p.theme.primary};
  [data-playback-active] {
    scroll-margin-top: calc(
      var(--app-header-height, 0px) + var(--sandbox-toolbar-height, 0px) + 16px
    );
  }
`;
