import { togglePresetPedal } from 'app/services/EffectsService/presets';
import { defaultEffects } from 'app/services/EffectsService/settings';

export const defaultGuitarTimbre = 'GtRhythmTele';

export const guitarOverdrive = {
  id: 'guitar-overdrive',
  name: 'Overdrive',
  settings: defaultEffects('distortedGuitar'),
};

export const defaultGuitarEffects = () =>
  togglePresetPedal(
    { ...defaultEffects(''), volume: guitarOverdrive.settings.volume },
    guitarOverdrive,
  );
