import {
  KeyboardEvent,
  PointerEvent,
  useCallback,
  useEffect,
  useId,
  useRef,
} from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { Note, notesActions } from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';
import { Timbre } from 'app/services/SynthesizerService';

export const useScreenNoteInput = () => {
  const dispatch = useDispatch();
  const { timbre } = useSelector(selectSettings);
  const instance = useId();
  const inputs = useRef(
    new Map<string, { note: Note; timbre: Timbre; source: string }>(),
  );
  const release = useCallback(
    (id: string) => {
      const voice = inputs.current.get(id);
      if (!voice) return;
      inputs.current.delete(id);
      dispatch(notesActions.muteNote(voice));
    },
    [dispatch],
  );
  const press = (id: string, note: Note) => {
    if (inputs.current.has(id)) return;
    const voice = { note, timbre, source: `${id}:play-along:${instance}` };
    inputs.current.set(id, voice);
    dispatch(notesActions.playNote(voice));
  };
  const releaseAll = useCallback(() => {
    Array.from(inputs.current.keys()).forEach(release);
  }, [release]);

  useEffect(() => {
    const onVisibility = () => {
      if (document.hidden) releaseAll();
    };
    window.addEventListener('blur', releaseAll);
    document.addEventListener('visibilitychange', onVisibility);
    return () => {
      window.removeEventListener('blur', releaseAll);
      document.removeEventListener('visibilitychange', onVisibility);
      releaseAll();
    };
  }, [releaseAll]);

  return (note: Note, key: string = note) => ({
    onPointerDown: (event: PointerEvent<HTMLButtonElement>) => {
      if (event.button !== 0 && event.pointerType === 'mouse') return;
      event.preventDefault();
      event.currentTarget.setPointerCapture?.(event.pointerId);
      press(`pointer:${event.pointerId}`, note);
    },
    onPointerUp: (event: PointerEvent<HTMLButtonElement>) =>
      release(`pointer:${event.pointerId}`),
    onPointerCancel: (event: PointerEvent<HTMLButtonElement>) =>
      release(`pointer:${event.pointerId}`),
    onLostPointerCapture: (event: PointerEvent<HTMLButtonElement>) =>
      release(`pointer:${event.pointerId}`),
    onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => {
      if (event.code === 'Enter' || event.code === 'Space') {
        event.preventDefault();
        if (!event.repeat) press(`key:${key}`, note);
      }
    },
    onKeyUp: (event: KeyboardEvent<HTMLButtonElement>) => {
      if (event.code === 'Enter' || event.code === 'Space')
        release(`key:${key}`);
    },
    onBlur: () => release(`key:${key}`),
  });
};
