import { Note } from 'app/services/NotesService';

export type NoteFlight = {
  id: number;
  note: Note;
  startedAt: number;
  releasedAt?: number;
};

// CSS pixels per millisecond, independent of BPM and animation frame rate.
export const FLIGHT_SPEED = 0.12;
// Longer than the time needed to cross the entire scene after release.
export const RELEASE_LIFETIME = 7000;

export const getFlightMotion = (
  flight: NoteFlight,
  now: number,
  originTop: number,
  keyHeight: number,
) => {
  const top = originTop - Math.max(0, now - flight.startedAt) * FLIGHT_SPEED;
  const bottom =
    originTop - Math.max(0, now - (flight.releasedAt ?? now)) * FLIGHT_SPEED;
  return { top, bottom, tailHeight: Math.max(0, bottom - top - keyHeight) };
};
