import { useLayoutEffect } from 'react';
import { useStore } from 'react-redux';

import { updateInstrumentEffects } from 'app/services/SynthesizerService';
import type { RootState } from 'app/services/types';

import { selectEffects } from './selectors';
import type { EffectsByTimbre } from './settings';
import { useEffectsSlice } from './slice';

export const useEffects = () => {
  useEffectsSlice();
  const store = useStore<RootState>();
  useLayoutEffect(() => {
    let previous: EffectsByTimbre | undefined;
    const update = () => {
      const { instruments } = selectEffects(store.getState());
      if (instruments === previous) return;
      previous = instruments;
      updateInstrumentEffects(instruments);
    };
    // Apply synchronously on dispatch, before a zero-delay note can start.
    update();
    return store.subscribe(update);
  }, [store]);
};
