import { useCallback, useEffect, useRef, useState } from 'react';

import { playMelody, stopMelody } from 'app/services/MelodiesService';
import { cropExpression } from 'app/services/MelodiesService/expression';
import { Melody } from 'app/services/MelodiesService/types';
import { loadSound, resumeAudio } from 'app/services/SynthesizerService';
import { useTuner } from 'app/services/TunerService/useTuner';

import { VOCAL_MAX_FREQUENCY, VocalNote, scoreVocalInterval } from './score';

const initial = () => ({
  status: 'ready' as 'ready' | 'playing' | 'paused' | 'finished',
  elapsed: -3000,
  expected: 0,
  matched: 0,
});

export const useKaraoke = (
  melody: Melody,
  line: VocalNote[],
  speed: number,
  guide: boolean,
  singingOctave: number,
) => {
  const microphone = useTuner(VOCAL_MAX_FREQUENCY);
  const input = {
    ...microphone,
    frequency:
      microphone.frequency === null
        ? null
        : microphone.frequency / 2 ** singingOctave,
  };
  const [state, setState] = useState(initial);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const current = useRef(state);
  const clock = useRef({ wall: 0, song: 0 });
  const generation = useRef({ id: 0 });
  const latestInput = useRef(input);
  latestInput.current = input;
  const duration = line.reduce(
    (end, note) => Math.max(end, note.start + note.duration),
    0,
  );
  const update = useCallback((next: typeof state) => {
    current.current = next;
    setState(next);
  }, []);
  const pause = useCallback(() => {
    generation.current.id++;
    setLoading(false);
    if (current.current.status === 'playing')
      update({ ...current.current, status: 'paused' });
    stopMelody();
  }, [update]);
  const reset = useCallback(() => {
    pause();
    update(initial());
    setError('');
  }, [pause, update]);

  useEffect(() => {
    reset();
    const pending = generation.current;
    return () => {
      pending.id++;
      stopMelody();
    };
  }, [line, speed, guide, reset]);

  useEffect(() => {
    if (input.status !== 'listening') pause();
  }, [input.status, pause]);

  useEffect(() => {
    const hidden = () => {
      if (document.hidden) pause();
    };
    window.addEventListener('blur', pause);
    document.addEventListener('visibilitychange', hidden);
    return () => {
      window.removeEventListener('blur', pause);
      document.removeEventListener('visibilitychange', hidden);
    };
  }, [pause]);

  useEffect(() => {
    if (state.status !== 'playing') return;
    const timer = window.setInterval(() => {
      const previous = current.current;
      if (previous.status !== 'playing') return;
      const wall = performance.now();
      const elapsed = Math.min(
        duration,
        clock.current.song + (wall - clock.current.wall) * speed,
      );
      const sample = latestInput.current;
      const fresh = wall - sample.sampledAt <= 240;
      const score = scoreVocalInterval(
        line,
        previous.elapsed,
        elapsed,
        fresh ? sample.frequency : null,
        elapsed - 120 * speed,
      );
      update({
        elapsed,
        status: elapsed >= duration ? 'finished' : 'playing',
        expected: previous.expected + score.expected,
        matched: previous.matched + score.matched,
      });
      if (elapsed >= duration) stopMelody();
    }, 40);
    return () => window.clearInterval(timer);
  }, [duration, line, speed, state.status, update]);

  const start = async () => {
    if (latestInput.current.status !== 'listening' || loading) return;
    const id = ++generation.current.id;
    setError('');
    setLoading(true);
    try {
      stopMelody();
      if (guide) await Promise.all([resumeAudio(), loadSound('grandpiano')]);
      if (id !== generation.current.id) return;
      const next =
        current.current.status === 'paused' ? current.current : initial();
      // Count-in is three real seconds at every speed.
      const elapsed =
        next.elapsed < 0 && next.status === 'ready'
          ? -3000 * speed
          : next.elapsed;
      clock.current = { song: elapsed, wall: performance.now() };
      update({ ...next, elapsed, status: 'playing' });
      if (guide) {
        const offset = Math.max(0, elapsed);
        void playMelody({
          ...melody,
          timbre: 'grandpiano',
          notes: line
            .filter(note => note.start + note.duration > offset)
            .map(note => ({
              ...note,
              start: (Math.max(offset, note.start) - elapsed) / speed,
              duration:
                (note.start + note.duration - Math.max(offset, note.start)) /
                speed,
              expression: cropExpression(
                note.expression,
                Math.max(0, (offset - note.start) / note.duration),
              ),
            })),
        });
      }
    } catch {
      if (id !== generation.current.id) return;
      setError('Could not load the guide. Try again or turn off guide notes.');
    } finally {
      if (id === generation.current.id) setLoading(false);
    }
  };

  return { ...state, input, loading, error, start, pause, reset, duration };
};
