import {
  KeyboardEvent,
  PointerEvent,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useSelector } from 'react-redux';
import styled, { css } from 'styled-components';

import {
  getMelodyDuration,
  selectMelodies,
} from 'app/services/MelodiesService';
import {
  MAX_NOTE_PITCH,
  NoteEditMode,
  editNoteSelection,
  getEditingStep,
  noteAtPitch,
  notePitch,
} from 'app/services/MelodiesService/editing';
import {
  getBeatsPerMeasure,
  getTimeSignature,
} from 'app/services/MelodiesService/meter';
import {
  Subdivision,
  getNormalizationOptions,
  normalizeMelody,
} from 'app/services/MelodiesService/normalization';
import {
  changeTempo,
  clampTempo,
  estimateTempo,
} from 'app/services/MelodiesService/tempo';
import { getNoteDuration } from 'app/services/MelodiesService/timing';
import { Melody, NoteInMelody } from 'app/services/MelodiesService/types';

import { MelodyActionButton, MelodyActionIcon } from './MelodyAction';
import { MelodyEditorIcon, MelodyEditorPopover } from './MelodyEditorAction';
import { RecordingNormalization } from './RecordingNormalization';

const DEFAULT_ROW_HEIGHT = 28;
const DEFAULT_BEAT_WIDTH = 96;
const ZOOM_STEP = 25;
const MIN_TIME_ZOOM = 25;
const MAX_TIME_ZOOM = 400;
const noteArrows = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'];
const rowHeightPresets = [
  { label: 'Short', percent: 75 },
  { label: 'Default', percent: 100 },
  { label: 'Tall', percent: 150 },
];
const LABEL_WIDTH = 52;
const RULER_HEIGHT = 26;
const allNotes = Array.from({ length: MAX_NOTE_PITCH + 1 }, (_, i) =>
  noteAtPitch(i),
);

interface Props {
  compact?: boolean;
  studio?: boolean;
  melody: Melody;
  onChange: (notes: NoteInMelody[], bpm: number) => void;
  onStop: () => void;
  onPlay?: (melody: Melody, noteIndex?: number) => void;
  isPlaying?: boolean;
  isPaused?: boolean;
  isAudition?: boolean;
  onPause?: () => void;
  onResume?: () => void;
  onSeek?: (position: number) => void;
  position?: number;
  timelinePlaying?: boolean;
}
type Snapshot = { notes: NoteInMelody[]; bpm: number };
type NoteChanges = ReadonlyMap<number, NoteInMelody>;
type Rectangle = { left: number; top: number; width: number; height: number };
type MarqueeGesture = {
  pointerId: number;
  x: number;
  y: number;
  toggle: boolean;
};
const formatPosition = (ms: number) =>
  `${Math.floor(ms / 60000)}:${((Math.floor(ms / 100) % 600) / 10)
    .toFixed(1)
    .padStart(4, '0')}`;

interface Gesture {
  index: number;
  pointerId: number;
  mode: NoteEditMode;
  indices: number[];
  x: number;
  y: number;
  scrollLeft: number;
  scrollTop: number;
  pixelsPerMs: number;
  rowHeight: number;
  step: number;
}

export const RecordingEditor = ({
  compact = false,
  studio = false,
  melody,
  onChange,
  onStop,
  onPlay,
  isPlaying = false,
  isPaused = false,
  isAudition = false,
  onPause,
  onResume,
  onSeek,
  position = 0,
}: Props) => {
  const [snapEnabled, setSnapEnabled] = useState(true);
  const [subdivision, setSubdivision] = useState<Subdivision>(4);
  const [zoom, setZoom] = useState(DEFAULT_BEAT_WIDTH);
  const [preferredRowHeight, setRowHeight] = useState(DEFAULT_ROW_HEIGHT);
  const [selection, setSelection] = useState<ReadonlySet<number>>(
    () => new Set(),
  );
  const [preview, setPreview] = useState<NoteChanges | null>(null);
  const [marquee, setMarquee] = useState<Rectangle | null>(null);
  const [past, setPast] = useState<Snapshot[]>([]);
  const [future, setFuture] = useState<Snapshot[]>([]);
  const skipClick = useRef(false);
  const gesture = useRef<Gesture | null>(null);
  const previewRef = useRef<NoteChanges | null>(null);
  const marqueeGesture = useRef<MarqueeGesture | null>(null);
  const lastNotes = useRef(melody.notes);
  const viewport = useRef<HTMLDivElement>(null);
  const timeline = useRef<HTMLDivElement>(null);
  const zoomAnchor = useRef<{
    x: number;
    y: number;
    time: number;
    row: number;
    horizontal: boolean;
    vertical: boolean;
  } | null>(null);
  const skipZoomScroll = useRef(false);
  const seeking = useRef<{ pointerId: number; original: number } | null>(null);
  const [pitchRange, setPitchRange] = useState(() => {
    const pitches = melody.notes.length
      ? melody.notes.map(event => notePitch(event.note))
      : [48];
    const low = Math.max(0, Math.min(...pitches) - 4);
    return {
      low,
      high: Math.min(
        MAX_NOTE_PITCH,
        Math.max(Math.max(...pitches) + 4, low + 11),
      ),
    };
  });
  const previousHigh = useRef(pitchRange.high);
  const initialScroll = useRef(false);
  useLayoutEffect(() => {
    const element = viewport.current;
    if (!compact || initialScroll.current || !element?.clientHeight) return;
    const firstPitch = notePitch(melody.notes[0]?.note ?? 'C4');
    element.scrollTop = Math.max(
      0,
      RULER_HEIGHT +
        (pitchRange.high - firstPitch) * preferredRowHeight -
        element.clientHeight / 2,
    );
    initialScroll.current = true;
  }, [compact, melody.notes, pitchRange.high, preferredRowHeight]);
  const [viewportSize, setViewportSize] = useState({ width: 0, height: 0 });
  const hintId = useId();
  const { soundingNoteIndices } = useSelector(selectMelodies);
  const estimate = useMemo(() => estimateTempo(melody.notes), [melody.notes]);
  const bpm =
    melody.bpm && Number.isFinite(melody.bpm) && melody.bpm > 0
      ? melody.bpm
      : estimate?.bpm ?? getNormalizationOptions(melody).bpm;
  const current = { notes: melody.notes, bpm };
  const beatMs = 60000 / bpm;
  const step = getEditingStep(
    { ...melody, bpm },
    snapEnabled ? subdivision : 0,
  );
  const pixelsPerMs = zoom / beatMs;
  const beatsPerMeasure = getBeatsPerMeasure(melody.timeSignature);
  const [countsPerMeasure, unit] = getTimeSignature(melody.timeSignature)
    .split('/')
    .map(Number);
  const quartersPerCount = 4 / unit;
  const beats = Math.max(
    beatsPerMeasure,
    Math.ceil((viewportSize.width - LABEL_WIDTH) / zoom),
    Math.ceil(getMelodyDuration(melody) / beatMs) + 2,
  );
  const { low: lowest, high: highestPitch } = pitchRange;
  useLayoutEffect(() => {
    const pitches = melody.notes.map(event => notePitch(event.note));
    const low = Math.max(
      0,
      Math.min(lowest, ...pitches.map(pitch => pitch - 4)),
    );
    const high = Math.min(
      MAX_NOTE_PITCH,
      Math.max(highestPitch, ...pitches.map(pitch => pitch + 4)),
    );
    if (low !== lowest || high !== highestPitch) setPitchRange({ low, high });
    if (!studio && viewport.current && highestPitch > previousHigh.current)
      viewport.current.scrollTop +=
        (highestPitch - previousHigh.current) * preferredRowHeight;
    previousHigh.current = highestPitch;
  }, [studio, melody.notes, lowest, highestPitch, preferredRowHeight]);
  const availableHeight = viewportSize.height - RULER_HEIGHT;
  const fitPitch = studio && availableHeight > 0;
  const minimumRows = highestPitch - lowest + 1;
  const rowCount = fitPitch
    ? Math.min(
        MAX_NOTE_PITCH + 1,
        Math.max(minimumRows, Math.round(availableHeight / preferredRowHeight)),
      )
    : minimumRows;
  const highest = Math.max(highestPitch, rowCount - 1);
  const rowHeight = fitPitch ? availableHeight / rowCount : preferredRowHeight;
  const gridHeight = fitPitch ? availableHeight : rowCount * rowHeight;
  const rows = Array.from({ length: rowCount }, (_, i) => highest - i);
  const selected =
    selection.size === 1 ? selection.values().next().value : null;
  const selectedNote = selected === null ? undefined : melody.notes[selected];

  useLayoutEffect(() => {
    const anchor = zoomAnchor.current;
    const element = viewport.current;
    if (!anchor || !element) return;
    if (anchor.horizontal)
      element.scrollLeft = Math.max(
        0,
        LABEL_WIDTH + anchor.time * pixelsPerMs - anchor.x,
      );
    if (anchor.vertical)
      element.scrollTop = Math.max(
        0,
        RULER_HEIGHT + anchor.row * rowHeight - anchor.y,
      );
    zoomAnchor.current = null;
  }, [zoom, rowHeight, pixelsPerMs]);

  useEffect(() => {
    if (skipZoomScroll.current) {
      skipZoomScroll.current = false;
      return;
    }
    const element = viewport.current;
    if (
      !element ||
      gesture.current ||
      marqueeGesture.current ||
      seeking.current
    )
      return;
    const x = LABEL_WIDTH + position * pixelsPerMs;
    if (
      x > element.scrollLeft + element.clientWidth - 30 ||
      x < element.scrollLeft + LABEL_WIDTH
    )
      element.scrollLeft = Math.max(0, x - element.clientWidth / 3);
  }, [position, pixelsPerMs]);

  useEffect(() => {
    const element = viewport.current;
    if (!element) return;
    const measure = () =>
      setViewportSize({
        width: element.clientWidth,
        height: element.clientHeight,
      });
    const resetGesture = () => {
      seeking.current = null;
      gesture.current = null;
      previewRef.current = null;
      setPreview(null);
      marqueeGesture.current = null;
      setMarquee(null);
    };
    measure();
    const observer =
      typeof ResizeObserver === 'undefined'
        ? undefined
        : new ResizeObserver(measure);
    observer?.observe(element);
    window.addEventListener('resize', measure);
    window.addEventListener('blur', resetGesture);
    return () => {
      observer?.disconnect();
      window.removeEventListener('resize', measure);
      window.removeEventListener('blur', resetGesture);
    };
  }, []);

  useEffect(() => {
    // Normalization or restoring the original starts a new editor history.
    if (melody.notes !== lastNotes.current) {
      setPast([]);
      setFuture([]);
      setSelection(new Set());
      seeking.current = null;
      gesture.current = null;
      previewRef.current = null;
      setPreview(null);
      marqueeGesture.current = null;
      setMarquee(null);
    }
    lastNotes.current = melody.notes;
  }, [melody.notes]);

  const apply = (snapshot: Snapshot) => {
    lastNotes.current = snapshot.notes;
    onChange(snapshot.notes, snapshot.bpm);
  };
  const commitSnapshot = (snapshot: Snapshot) => {
    setPast(history => [...history.slice(-99), current]);
    setFuture([]);
    apply(snapshot);
  };
  const commitNotes = (changes: NoteChanges) => {
    if (
      Array.from(changes).every(([index, note]) => {
        const original = melody.notes[index];
        return (
          original.note === note.note &&
          original.start === note.start &&
          original.duration === note.duration
        );
      })
    )
      return;
    commitSnapshot({
      bpm,
      notes: melody.notes.map((event, index) => changes.get(index) ?? event),
    });
  };
  const commit = (index: number, note: NoteInMelody) =>
    commitNotes(new Map([[index, note]]));
  const selectNote = (index: number | null) =>
    setSelection(new Set(index === null ? [] : [index]));
  const toggleNotes = (indices: number[]) => {
    setSelection(current => {
      const next = new Set(current);
      for (const index of indices) {
        if (!next.delete(index)) next.add(index);
      }
      return next;
    });
  };
  const editWithArrow = (event: KeyboardEvent, index: number) => {
    if (!noteArrows.includes(event.key)) return;
    event.preventDefault();
    const horizontal = event.key === 'ArrowLeft' || event.key === 'ArrowRight';
    const direction =
      event.key === 'ArrowLeft' || event.key === 'ArrowDown' ? -1 : 1;
    commitNotes(
      editNoteSelection(
        melody.notes,
        studio ? Array.from(selection) : [index],
        index,
        event.shiftKey && horizontal ? 'resize-end' : 'move',
        horizontal ? direction * (step || 10) : 0,
        horizontal ? 0 : direction,
        step,
      ),
    );
  };
  const cancel = () => {
    if (previewRef.current) skipClick.current = true;
    gesture.current = null;
    previewRef.current = null;
    setPreview(null);
    marqueeGesture.current = null;
    setMarquee(null);
  };
  const changeZoom = (
    nextZoom: number,
    nextRowHeight: number,
    clientX?: number,
  ) => {
    if (nextZoom === zoom && nextRowHeight === preferredRowHeight) return;
    cancel();
    seeking.current = null;
    const element = viewport.current;
    if (element) {
      const cursorX = LABEL_WIDTH + position * pixelsPerMs - element.scrollLeft;
      const pointerX =
        clientX !== undefined
          ? Math.max(
              LABEL_WIDTH,
              Math.min(
                element.clientWidth,
                clientX -
                  element.getBoundingClientRect().left -
                  element.clientLeft,
              ),
            )
          : undefined;
      const x =
        pointerX ??
        (cursorX >= LABEL_WIDTH && cursorX <= element.clientWidth - 20
          ? cursorX
          : LABEL_WIDTH + Math.max(0, element.clientWidth - LABEL_WIDTH) / 2);
      const selectedY = selectedNote
        ? RULER_HEIGHT +
          (highest - notePitch(selectedNote.note) + 0.5) * rowHeight -
          element.scrollTop
        : -1;
      const y =
        selectedY >= RULER_HEIGHT && selectedY <= element.clientHeight
          ? selectedY
          : RULER_HEIGHT + Math.max(0, element.clientHeight - RULER_HEIGHT) / 2;
      zoomAnchor.current = {
        x,
        y,
        time: (element.scrollLeft + x - LABEL_WIDTH) / pixelsPerMs,
        row: (element.scrollTop + y - RULER_HEIGHT) / rowHeight,
        horizontal: nextZoom !== zoom,
        vertical: !studio && nextRowHeight !== preferredRowHeight,
      };
    }
    skipZoomScroll.current = nextZoom !== zoom;
    setZoom(nextZoom);
    setRowHeight(nextRowHeight);
  };
  const addNote = (
    time = position,
    pitch = notePitch(selectedNote?.note ?? melody.notes[0]?.note ?? 'C4'),
  ) => {
    const start = Math.max(
      0,
      Math.round(step ? Math.round(time / step) * step : time),
    );
    const duration = getNoteDuration(
      selectedNote ?? { note: 'C4', start: 0, duration: beatMs },
    );
    const note = {
      note: noteAtPitch(pitch),
      start,
      duration: Math.max(
        1,
        Math.round(step ? Math.round(duration / step) * step : duration),
      ),
    };
    commitSnapshot({ bpm, notes: [...melody.notes, note] });
    selectNote(melody.notes.length);
  };
  const removeNote = () => {
    if (!selection.size) return;
    cancel();
    commitSnapshot({
      bpm,
      notes: melody.notes.filter((_, index) => !selection.has(index)),
    });
    selectNote(null);
  };
  const timeAt = (x: number) =>
    Math.max(
      0,
      (x -
        (timeline.current?.getBoundingClientRect().left ?? 0) -
        LABEL_WIDTH) /
        pixelsPerMs,
    );
  const beginSeek = (event: PointerEvent<HTMLElement>) => {
    if (event.button !== 0 || !onSeek || !melody.notes.length) return;
    event.stopPropagation();
    if (studio) selectNote(null);
    event.currentTarget.setPointerCapture?.(event.pointerId);
    seeking.current = { pointerId: event.pointerId, original: position };
    onSeek(timeAt(event.clientX));
  };
  const begin = (
    event: PointerEvent<HTMLElement>,
    index: number,
    mode: NoteEditMode,
  ) => {
    if (event.button !== 0 || gesture.current) return;
    event.stopPropagation();
    if (studio && event.ctrlKey) {
      event.preventDefault();
      skipClick.current = true;
      toggleNotes([index]);
      return;
    }
    skipClick.current = false;
    const indices = selection.has(index) ? Array.from(selection) : [index];
    if (!selection.has(index)) selectNote(index);
    event.currentTarget.setPointerCapture?.(event.pointerId);
    gesture.current = {
      index,
      mode,
      pointerId: event.pointerId,
      indices,
      x: event.clientX,
      y: event.clientY,
      scrollLeft: viewport.current?.scrollLeft ?? 0,
      scrollTop: viewport.current?.scrollTop ?? 0,
      pixelsPerMs,
      rowHeight,
      step,
    };
  };
  const move = (event: PointerEvent) => {
    const drag = gesture.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    const dx =
      event.clientX -
      drag.x +
      (viewport.current?.scrollLeft ?? 0) -
      drag.scrollLeft;
    const dy =
      event.clientY -
      drag.y +
      (viewport.current?.scrollTop ?? 0) -
      drag.scrollTop;
    if (!previewRef.current && Math.abs(dx) < 3 && Math.abs(dy) < 3) return;
    const changes = editNoteSelection(
      melody.notes,
      drag.indices,
      drag.index,
      drag.mode,
      dx / drag.pixelsPerMs,
      Math.round(-dy / drag.rowHeight),
      drag.step,
    );
    previewRef.current = changes;
    setPreview(changes);
  };
  const end = (event: PointerEvent) => {
    const drag = gesture.current;
    if (!drag || drag.pointerId !== event.pointerId) return;
    move(event);
    if (previewRef.current) commitNotes(previewRef.current);
    cancel();
  };
  const audition = (index: number) => {
    selectNote(index);
    onPlay?.(
      { ...melody, bpm, notes: [{ ...melody.notes[index], start: 0 }] },
      index,
    );
  };
  const rowInset = Math.min(1, rowHeight / 4);
  const noteHeight = Math.max(1, rowHeight - 2 * rowInset);
  const noteBounds = (note: NoteInMelody): Rectangle => {
    const top =
      RULER_HEIGHT + rowInset + (highest - notePitch(note.note)) * rowHeight;
    return {
      left: LABEL_WIDTH + note.start * pixelsPerMs,
      top:
        studio && rowHeight < 2
          ? Math.min(top, RULER_HEIGHT + gridHeight - noteHeight)
          : top,
      width: Math.max(4, getNoteDuration(note) * pixelsPerMs),
      height: noteHeight,
    };
  };
  const beginMarquee = (event: PointerEvent<HTMLDivElement>) => {
    if (!studio || event.button !== 0 || marqueeGesture.current) return;
    const rect = event.currentTarget.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    if (event.pointerType === 'touch' || x < LABEL_WIDTH || y < RULER_HEIGHT) {
      if (!event.ctrlKey) selectNote(null);
      return;
    }
    marqueeGesture.current = {
      pointerId: event.pointerId,
      x,
      y,
      toggle: event.ctrlKey,
    };
    event.currentTarget.setPointerCapture?.(event.pointerId);
  };
  const marqueeBounds = (
    event: PointerEvent<HTMLDivElement>,
    start: MarqueeGesture,
  ): Rectangle | null => {
    const rect = event.currentTarget.getBoundingClientRect();
    const x = Math.max(
      LABEL_WIDTH,
      Math.min(LABEL_WIDTH + beats * zoom, event.clientX - rect.left),
    );
    const y = Math.max(
      RULER_HEIGHT,
      Math.min(RULER_HEIGHT + gridHeight, event.clientY - rect.top),
    );
    const width = Math.abs(x - start.x);
    const height = Math.abs(y - start.y);
    if (width < 3 && height < 3) return null;
    return {
      left: Math.min(x, start.x),
      top: Math.min(y, start.y),
      width,
      height,
    };
  };
  const finishMarquee = (
    event: PointerEvent<HTMLDivElement>,
    start: MarqueeGesture,
  ) => {
    const bounds = marqueeBounds(event, start);
    const hits = bounds
      ? melody.notes.flatMap((note, index) => {
          const box = noteBounds(note);
          return box.left < bounds.left + bounds.width &&
            box.left + box.width > bounds.left &&
            box.top < bounds.top + bounds.height &&
            box.top + box.height > bounds.top
            ? [index]
            : [];
        })
      : [];
    if (start.toggle) toggleNotes(hits);
    else setSelection(new Set(hits));
    marqueeGesture.current = null;
    setMarquee(null);
  };

  const Button = compact ? MelodyActionButton : 'button';
  const tempoDetails = (
    <Hint>
      {estimate ? (
        <>
          Estimated tempo: {estimate.bpm} BPM
          {estimate.confidence === 'low' ? ' (approximate)' : ''}.{' '}
          <button
            type="button"
            onClick={() =>
              commitSnapshot({ notes: melody.notes, bpm: estimate.bpm })
            }
          >
            Accept estimate
          </button>
          {estimate.alternatives.length > 0 && (
            <>
              {' '}
              Other options:{' '}
              {estimate.alternatives.map(value => (
                <button
                  type="button"
                  key={value}
                  onClick={() =>
                    commitSnapshot({ notes: melody.notes, bpm: value })
                  }
                >
                  {value} BPM
                </button>
              ))}
            </>
          )}
        </>
      ) : (
        'Not enough rhythmic events for a reliable tempo estimate.'
      )}{' '}
      Change BPM to speed up or slow down the melody. Use the estimate to move
      the grid without changing playback speed.
    </Hint>
  );
  const timeZoomPercent = Math.round((zoom / DEFAULT_BEAT_WIDTH) * 100);
  const pitchZoomPercent = Math.round(
    (preferredRowHeight / DEFAULT_ROW_HEIGHT) * 100,
  );
  const changeTimeZoom = (percent: number, clientX?: number) =>
    changeZoom(
      (DEFAULT_BEAT_WIDTH * percent) / 100,
      preferredRowHeight,
      clientX,
    );
  const pinch = useRef({ percent: timeZoomPercent, change: changeTimeZoom });
  pinch.current = { percent: timeZoomPercent, change: changeTimeZoom };
  useEffect(() => {
    const element = viewport.current;
    if (!element) return;
    let wheelZoom = 100;
    let lastWheel = -Infinity;
    let gestureStartZoom: number | undefined;
    const clamp = (percent: number) =>
      Math.max(MIN_TIME_ZOOM, Math.min(MAX_TIME_ZOOM, percent));
    const apply = (percent: number, clientX: number) =>
      pinch.current.change(
        Math.round(clamp(percent) / ZOOM_STEP) * ZOOM_STEP,
        clientX,
      );
    // Chromium and Firefox report a pinch as a wheel event with Control held.
    const handleWheel = (event: WheelEvent) => {
      if (!event.ctrlKey) return;
      event.preventDefault();
      if (gestureStartZoom !== undefined) return;
      if (event.timeStamp - lastWheel > 180) wheelZoom = pinch.current.percent;
      lastWheel = event.timeStamp;
      const unit =
        event.deltaMode === WheelEvent.DOM_DELTA_LINE
          ? 16
          : event.deltaMode === WheelEvent.DOM_DELTA_PAGE
          ? element.clientHeight
          : 1;
      wheelZoom = clamp(wheelZoom * Math.exp((-event.deltaY * unit) / 150));
      apply(wheelZoom, event.clientX);
    };
    // Safari reports the scale relative to the start of the gesture.
    const startGesture = (event: Event) => {
      event.preventDefault();
      gestureStartZoom = pinch.current.percent;
    };
    const changeGesture = (event: Event) => {
      if (gestureStartZoom === undefined) return;
      event.preventDefault();
      const { scale, clientX } = event as MouseEvent & { scale: number };
      if (Number.isFinite(scale) && scale > 0)
        apply(gestureStartZoom * scale, clientX);
    };
    const endGesture = () => {
      gestureStartZoom = undefined;
      lastWheel = -Infinity;
    };
    element.addEventListener('wheel', handleWheel, { passive: false });
    element.addEventListener('gesturestart', startGesture, { passive: false });
    element.addEventListener('gesturechange', changeGesture, {
      passive: false,
    });
    element.addEventListener('gestureend', endGesture);
    return () => {
      element.removeEventListener('wheel', handleWheel);
      element.removeEventListener('gesturestart', startGesture);
      element.removeEventListener('gesturechange', changeGesture);
      element.removeEventListener('gestureend', endGesture);
    };
  }, []);
  const changePitchZoom = (percent: number) =>
    changeZoom(zoom, (DEFAULT_ROW_HEIGHT * percent) / 100);
  const resetZoom = () => changeZoom(DEFAULT_BEAT_WIDTH, DEFAULT_ROW_HEIGHT);
  const defaultZoom = timeZoomPercent === 100 && pitchZoomPercent === 100;
  const timeZoom = (
    <ZoomControl>
      {compact && 'Time zoom'}
      <input
        type="range"
        aria-label="Time zoom"
        aria-valuetext={`${timeZoomPercent}%`}
        min={MIN_TIME_ZOOM}
        max={MAX_TIME_ZOOM}
        step={ZOOM_STEP}
        value={timeZoomPercent}
        onChange={event => changeTimeZoom(+event.target.value)}
      />
      <output aria-hidden="true">{timeZoomPercent}%</output>
    </ZoomControl>
  );
  const pitchZoom = (
    <ZoomControl>
      Pitch zoom
      <input
        type="range"
        aria-valuetext={`${pitchZoomPercent}%`}
        min={50}
        max={200}
        step={ZOOM_STEP}
        value={pitchZoomPercent}
        onChange={event => changePitchZoom(+event.target.value)}
      />
      <output aria-hidden="true">{pitchZoomPercent}%</output>
    </ZoomControl>
  );
  const help = (
    <Hint id={hintId}>
      Drag a note or use the arrow keys to move it. Resize it at either edge or
      use Shift + ←/→. Click a note or press Enter to hear it. Escape cancels
      the edit. Double-click empty space to add a note. Delete or Backspace
      removes the selection. To jump to a point in the take, click the ruler or
      drag the playhead. Pinch the grid to zoom in or out in time.
      {studio &&
        ' Drag across empty space to select notes. Hold Ctrl while clicking or dragging to toggle notes in the selection. Press Space to play or pause. With no notes selected, press ↑ to return to the start or ←/→ to jump between notes.'}
    </Hint>
  );
  const selectionControls =
    selectedNote && selected !== null ? (
      <Toolbar
        key={`${selected}:${selectedNote.start}:${selectedNote.duration}:${selectedNote.note}`}
        aria-label="Selected note"
      >
        <strong>Note {selected + 1}</strong>
        <label>
          Pitch
          <select
            value={selectedNote.note}
            onChange={event =>
              commit(selected, {
                ...selectedNote,
                note: event.target.value as NoteInMelody['note'],
              })
            }
          >
            {allNotes.map(note => (
              <option key={note}>{note}</option>
            ))}
          </select>
        </label>
        <label>
          Start, ms
          <input
            type="number"
            min={0}
            step={1}
            defaultValue={selectedNote.start}
            onKeyDown={event => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            onBlur={event => {
              const value = event.currentTarget.valueAsNumber;
              if (Number.isFinite(value))
                commit(selected, {
                  ...selectedNote,
                  start: Math.max(0, Math.round(value)),
                });
            }}
          />
        </label>
        <label>
          Duration, ms
          <input
            type="number"
            min={1}
            step={1}
            defaultValue={getNoteDuration(selectedNote)}
            onKeyDown={event => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            onBlur={event => {
              const value = event.currentTarget.valueAsNumber;
              if (Number.isFinite(value))
                commit(selected, {
                  ...selectedNote,
                  duration: Math.max(1, Math.round(value)),
                });
            }}
          />
        </label>
        <span>Exact values without snapping</span>
      </Toolbar>
    ) : null;
  const playLabel =
    isPlaying && !isAudition ? 'Pause' : isPaused ? 'Resume' : 'Play melody';

  const transport = !studio ? (
    <>
      <Transport aria-label="Editor playback">
        <Button
          type="button"
          aria-label={playLabel}
          title={playLabel}
          disabled={!onPlay || !melody.notes.length}
          onClick={() => {
            if (isPlaying && !isAudition) (onPause ?? onStop)();
            else if (isPaused && onResume) onResume();
            else onPlay?.({ ...melody, bpm });
          }}
        >
          {compact ? (
            isPlaying && !isAudition ? (
              <MelodyEditorIcon icon="pause" />
            ) : (
              <MelodyActionIcon action="play" />
            )
          ) : (
            playLabel
          )}
        </Button>
        <Button
          type="button"
          disabled={!isPlaying && !isPaused && position === 0}
          aria-label="Stop"
          title="Stop"
          onClick={onStop}
        >
          {compact ? <MelodyActionIcon action="stop" /> : 'Stop'}
        </Button>
        <output role="timer" aria-label="Playback position">
          {formatPosition(position)} /{' '}
          {formatPosition(getMelodyDuration(melody))}
        </output>
        <label>
          {compact ? 'BPM' : 'Tempo, BPM'}
          <input
            aria-label="Tempo, BPM"
            key={bpm}
            type="number"
            min={40}
            max={220}
            step={1}
            defaultValue={bpm}
            onKeyDown={event => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            onBlur={event => {
              const value = event.currentTarget.valueAsNumber;
              if (!Number.isFinite(value)) {
                event.currentTarget.value = String(bpm);
                return;
              }
              const next = clampTempo(value);
              event.currentTarget.value = String(next);
              if (next !== bpm)
                commitSnapshot({
                  bpm: next,
                  notes: changeTempo(melody.notes, bpm, next),
                });
            }}
          />
        </label>
        <RecordingNormalization
          compact={compact}
          key={bpm}
          melody={{ ...melody, bpm }}
          durationsOnly
          canRestore={false}
          isPlaying={isPlaying}
          onStop={onStop}
          onPreview={piece => onPlay?.(piece)}
          onRestore={() => {}}
          onApply={options => {
            const result = normalizeMelody({ ...melody, bpm }, options).melody;
            commitSnapshot({ notes: result.notes, bpm: result.bpm! });
          }}
        />
        {compact && (
          <MelodyEditorPopover label="Tempo estimate" icon="tempo">
            {tempoDetails}
          </MelodyEditorPopover>
        )}
      </Transport>
      {!compact && tempoDetails}
    </>
  ) : null;

  const editControls = (
    <Toolbar role="group" aria-label="Note editing">
      {!compact && (
        <MelodyEditorPopover label="Row height" icon="row-height" anchored>
          <RowHeightPresets role="group" aria-label="Row height presets">
            {rowHeightPresets.map(({ label, percent }) => (
              <MelodyActionButton
                key={percent}
                type="button"
                $withLabel
                aria-pressed={pitchZoomPercent === percent}
                onClick={() => changePitchZoom(percent)}
              >
                {label}
              </MelodyActionButton>
            ))}
          </RowHeightPresets>
          {pitchZoom}
        </MelodyEditorPopover>
      )}
      <MelodyActionButton
        type="button"
        aria-label="Add note"
        title="Add note"
        onClick={() => addNote()}
      >
        <MelodyEditorIcon icon="add" />
      </MelodyActionButton>
      <MelodyActionButton
        type="button"
        aria-label="Delete note"
        title="Delete note"
        disabled={!selection.size}
        onClick={removeNote}
      >
        <MelodyEditorIcon icon="delete" />
      </MelodyActionButton>
      <MelodyActionButton
        type="button"
        role="checkbox"
        aria-label="Snap to grid"
        title="Snap to grid"
        aria-checked={snapEnabled}
        onClick={() => setSnapEnabled(!snapEnabled)}
      >
        <MelodyEditorIcon icon="snap" />
      </MelodyActionButton>
      <label>
        {!compact && <MelodyEditorIcon icon="grid" />}
        <select
          aria-label="Grid"
          value={subdivision}
          disabled={!snapEnabled}
          onChange={event => setSubdivision(+event.target.value as Subdivision)}
        >
          <option value={1}>1/4</option>
          <option value={2}>1/8</option>
          <option value={4}>1/16</option>
          <option value={8}>1/32</option>
          <option value={3}>1/8 triplets</option>
        </select>
      </label>
      <span>
        {compact
          ? melody.timeSignature ?? '4/4'
          : `${bpm} BPM · ${melody.timeSignature ?? '4/4'}`}
      </span>
      <MelodyActionButton
        type="button"
        aria-label="Undo"
        title="Undo"
        disabled={!past.length}
        onClick={() => {
          selectNote(null);
          setPast(past.slice(0, -1));
          setFuture([current, ...future]);
          apply(past[past.length - 1]);
        }}
      >
        <MelodyEditorIcon icon="undo" />
      </MelodyActionButton>
      <MelodyActionButton
        type="button"
        aria-label="Redo"
        title="Redo"
        disabled={!future.length}
        onClick={() => {
          selectNote(null);
          setPast([...past, current]);
          setFuture(future.slice(1));
          apply(future[0]);
        }}
      >
        <MelodyEditorIcon icon="redo" />
      </MelodyActionButton>
      {(compact || studio) && (
        <>
          <MelodyEditorPopover
            label="Note parameters"
            icon="edit"
            disabled={!selectedNote}
          >
            {selectionControls}
          </MelodyEditorPopover>
          {compact && (
            <MelodyEditorPopover label="Timeline zoom" icon="zoom">
              <Toolbar aria-label="Timeline zoom">
                {timeZoom}
                {pitchZoom}
                <button
                  type="button"
                  disabled={defaultZoom}
                  onClick={resetZoom}
                >
                  Reset zoom
                </button>
              </Toolbar>
            </MelodyEditorPopover>
          )}
          <MelodyEditorPopover label="Editor help" icon="help">
            {help}
          </MelodyEditorPopover>
        </>
      )}
    </Toolbar>
  );

  return (
    <Editor
      $compact={compact}
      $studio={studio}
      aria-label="Melody editor"
      onKeyDown={event => {
        if (
          studio &&
          (event.code === 'Space' ||
            (!selection.size &&
              ['ArrowUp', 'ArrowLeft', 'ArrowRight'].includes(event.key)))
        )
          return;
        event.stopPropagation();
        if (event.key === 'Escape') {
          if (seeking.current) onSeek?.(seeking.current.original);
          seeking.current = null;
          cancel();
          if (studio) selectNote(null);
        }
        const target = event.target as HTMLElement;
        if (target.closest('input, select, textarea, [contenteditable="true"]'))
          return;
        if (studio && selection.size)
          editWithArrow(event, selection.values().next().value);
        if (event.key === 'Delete' || event.key === 'Backspace') {
          event.preventDefault();
          removeNote();
        } else if (event.key === 'Insert') {
          event.preventDefault();
          addNote();
        }
      }}
    >
      {transport}
      {compact && editControls}
      {!compact && !studio && help}
      {!studio && !melody.notes.length && (
        <Hint>
          No notes yet. Use the button or double-click the grid to add your
          first note.
        </Hint>
      )}
      {!compact && (
        <GridControls
          $studio={studio}
          role="group"
          aria-label="Note grid controls"
        >
          <GridEditTools>{editControls}</GridEditTools>
          <TimeZoomGroup>
            <MelodyActionButton
              type="button"
              aria-label="Zoom out on timeline"
              title="Zoom out on timeline"
              disabled={timeZoomPercent === MIN_TIME_ZOOM}
              onClick={() => changeTimeZoom(timeZoomPercent - ZOOM_STEP)}
            >
              <MelodyEditorIcon icon="zoom-out" />
            </MelodyActionButton>
            {timeZoom}
            <MelodyActionButton
              type="button"
              aria-label="Zoom in on timeline"
              title="Zoom in on timeline"
              disabled={timeZoomPercent === MAX_TIME_ZOOM}
              onClick={() => changeTimeZoom(timeZoomPercent + ZOOM_STEP)}
            >
              <MelodyEditorIcon icon="zoom" />
            </MelodyActionButton>
            <MelodyActionButton
              type="button"
              aria-label="Reset zoom"
              title="Reset zoom"
              disabled={defaultZoom}
              onClick={resetZoom}
            >
              <MelodyActionIcon action="restore" />
            </MelodyActionButton>
          </TimeZoomGroup>
        </GridControls>
      )}
      <Viewport
        ref={viewport}
        $studio={studio}
        tabIndex={0}
        aria-label="Note time grid"
      >
        {studio && !melody.notes.length && (
          <EmptyGridHint>
            No notes yet. Use the button or double-click the grid to add your
            first note.
          </EmptyGridHint>
        )}
        <Timeline
          ref={timeline}
          onPointerDown={beginMarquee}
          onContextMenu={event => {
            if (studio && event.ctrlKey) event.preventDefault();
          }}
          onDoubleClick={event => {
            if (
              (event.target as HTMLElement).closest(
                '[data-note-index], [data-ruler], [data-playhead]',
              )
            )
              return;
            const rect = event.currentTarget.getBoundingClientRect();
            const row = Math.floor(
              (event.clientY - rect.top - RULER_HEIGHT) / rowHeight,
            );
            if (
              event.clientX - rect.left < LABEL_WIDTH ||
              row < 0 ||
              row >= rows.length
            )
              return;
            addNote(timeAt(event.clientX), highest - row);
          }}
          style={{
            width: LABEL_WIDTH + beats * zoom,
            height: RULER_HEIGHT + gridHeight,
          }}
          onPointerMove={event => {
            const drag = marqueeGesture.current;
            if (seeking.current?.pointerId === event.pointerId)
              onSeek?.(timeAt(event.clientX));
            else if (drag?.pointerId === event.pointerId)
              setMarquee(marqueeBounds(event, drag));
            else move(event);
          }}
          onPointerUp={event => {
            const drag = marqueeGesture.current;
            if (seeking.current?.pointerId === event.pointerId) {
              onSeek?.(timeAt(event.clientX));
              seeking.current = null;
            } else if (drag?.pointerId === event.pointerId)
              finishMarquee(event, drag);
            else end(event);
          }}
          onPointerCancel={event => {
            if (seeking.current?.pointerId === event.pointerId)
              seeking.current = null;
            if (
              gesture.current?.pointerId === event.pointerId ||
              marqueeGesture.current?.pointerId === event.pointerId
            )
              cancel();
          }}
          onLostPointerCapture={event => {
            if (seeking.current?.pointerId === event.pointerId)
              seeking.current = null;
            if (
              gesture.current?.pointerId === event.pointerId ||
              marqueeGesture.current?.pointerId === event.pointerId
            )
              cancel();
          }}
        >
          <Ruler
            data-ruler
            onPointerDown={beginSeek}
            style={{ width: beats * zoom, marginLeft: LABEL_WIDTH }}
          >
            {Array.from(
              { length: Math.ceil(beats / quartersPerCount) },
              (_, count) => (
                <span
                  key={count}
                  style={{ left: count * quartersPerCount * zoom }}
                >
                  {Math.floor(count / countsPerMeasure) + 1}.
                  {(count % countsPerMeasure) + 1}
                </span>
              ),
            )}
          </Ruler>
          <Grid
            $rowHeight={rowHeight}
            style={{
              left: LABEL_WIDTH,
              width: beats * zoom,
              height: gridHeight,
              backgroundSize: `${zoom / subdivision}px ${rowHeight}px, ${
                zoom * quartersPerCount
              }px 100%, ${zoom * beatsPerMeasure}px 100%`,
            }}
          />
          <PitchLabels style={{ height: gridHeight }}>
            {rows.map((pitch, row) => (
              <PitchLabel
                key={pitch}
                $black={noteAtPitch(pitch).includes('#')}
                $rowHeight={rowHeight}
                style={{ top: row * rowHeight }}
              >
                {noteAtPitch(pitch)}
              </PitchLabel>
            ))}
          </PitchLabels>
          <Playhead
            data-playhead
            aria-label="Playhead"
            data-position={Math.round(position)}
            style={{
              left: LABEL_WIDTH + position * pixelsPerMs,
              height: RULER_HEIGHT + gridHeight,
            }}
          >
            <PlayheadGrip
              role="slider"
              tabIndex={0}
              aria-label="Playhead position"
              aria-valuemin={0}
              aria-valuemax={getMelodyDuration(melody)}
              aria-valuenow={Math.round(position)}
              aria-valuetext={formatPosition(position)}
              aria-disabled={!onSeek || !melody.notes.length}
              onPointerDown={beginSeek}
              onKeyDown={event => {
                const next =
                  event.key === 'Home'
                    ? 0
                    : event.key === 'End'
                    ? getMelodyDuration(melody)
                    : !studio && event.key === 'ArrowLeft'
                    ? Math.max(0, position - beatMs)
                    : !studio && event.key === 'ArrowRight'
                    ? Math.min(getMelodyDuration(melody), position + beatMs)
                    : undefined;
                if (next !== undefined) {
                  event.preventDefault();
                  onSeek?.(next);
                }
              }}
            />
          </Playhead>
          {marquee && <SelectionRectangle aria-hidden="true" style={marquee} />}
          {melody.notes.map((original, index) => {
            const note = preview?.get(index) ?? original;
            const duration = getNoteDuration(note);
            const { left, top, width } = noteBounds(note);
            const label = `Note ${index + 1}: ${note.note}`;
            return (
              <NoteBlock
                key={index}
                data-note-index={index}
                role="button"
                tabIndex={0}
                aria-label={label}
                aria-pressed={selection.has(index)}
                aria-describedby={compact ? undefined : hintId}
                title={`${note.note}: start ${note.start} ms, duration ${duration} ms`}
                $rowHeight={rowHeight}
                $selected={selection.has(index)}
                $sounding={soundingNoteIndices.includes(index)}
                style={{ left, top, width }}
                onFocus={() => {
                  if (!selection.has(index)) selectNote(index);
                }}
                onClick={() => {
                  if (skipClick.current) {
                    skipClick.current = false;
                    return;
                  }
                  audition(index);
                }}
                onPointerDown={event => begin(event, index, 'move')}
                onKeyDown={event => {
                  if (event.key === 'Enter' || (!studio && event.key === ' ')) {
                    event.preventDefault();
                    audition(index);
                    return;
                  }
                  if (!studio) editWithArrow(event, index);
                }}
              >
                <Handle
                  aria-hidden="true"
                  $end={false}
                  onPointerDown={event => begin(event, index, 'resize-start')}
                />
                <span>{note.note}</span>
                <Handle
                  aria-hidden="true"
                  $end
                  onPointerDown={event => begin(event, index, 'resize-end')}
                />
              </NoteBlock>
            );
          })}
        </Timeline>
      </Viewport>
      {!compact &&
        !studio &&
        (selectionControls ?? (
          <Hint>Select a note to set its exact pitch, start and duration.</Hint>
        ))}
    </Editor>
  );
};

