import { useId, useLayoutEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { selectEffects } from 'app/services/EffectsService/selectors';
import { defaultEffects } from 'app/services/EffectsService/settings';
import type { Melody } from 'app/services/MelodiesService/types';
import { ExportFormat, downloadMelody } from 'app/services/MelodyExportService';
import { MelodyExportError } from 'app/services/MelodyExportService/errors';
import { scoreFormats } from 'app/services/MelodyExportService/scoreFormats';
import { selectSettings } from 'app/services/SettingsService';

import type { GuitarRecording } from './GuitarRecordingExport';
import { useHeaderPopupDismiss } from './HeaderPopup';
import { MelodyActionButton, MelodyActionIcon } from './MelodyAction';

const formats: { format: ExportFormat; label: string }[] = [
  { format: 'midi', label: 'MIDI · notes' },
  { format: 'wav', label: 'WAV · uncompressed audio' },
  { format: 'mp3', label: 'MP3 · compressed audio' },
  ...Object.entries(scoreFormats).map(([format, { label }]) => ({
    format: format as keyof typeof scoreFormats,
    label: `PDF · ${label}`,
  })),
];

const menuWidth = 256;
const inset = 8;
const offset = 4;

export const MelodyExport = ({
  melody,
  showLabel = false,
  audioRecording,
}: {
  melody: Melody;
  showLabel?: boolean;
  audioRecording?: GuitarRecording;
}) => {
  const [open, setOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const pending = useRef(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const popup = useRef<HTMLDivElement>(null);
  const id = useId();
  const { instruments } = useSelector(selectEffects);
  const { optimizeTablature = false, optimizeFullTablature = false } =
    useSelector(selectSettings);
  const hasNotes = melody.notes.length > 0;
  const hasTake = !!audioRecording?.hasTake;
  useHeaderPopupDismiss(open, setOpen, trigger, popup);

  useLayoutEffect(() => {
    const button = trigger.current;
    const panel = popup.current;
    if (!open || !button || !panel) return;
    const position = () => {
      const anchor = button.getBoundingClientRect();
      const viewportWidth =
        document.documentElement.clientWidth || window.innerWidth;
      const width = Math.min(menuWidth, viewportWidth - 2 * inset);
      const below = window.innerHeight - anchor.bottom - inset - offset;
      const above = anchor.top - inset - offset;
      const openBelow = below >= 320 || below >= above;
      panel.style.left = `${Math.max(
        inset,
        Math.min(anchor.right - width, viewportWidth - width - inset),
      )}px`;
      panel.style.top = openBelow ? `${anchor.bottom + offset}px` : 'auto';
      panel.style.bottom = openBelow
        ? 'auto'
        : `${window.innerHeight - anchor.top + offset}px`;
      panel.style.maxHeight = `${Math.max(0, openBelow ? below : above)}px`;
    };
    position();
    panel.querySelector<HTMLButtonElement>('button:enabled')?.focus({
      preventScroll: true,
    });
    window.addEventListener('resize', position);
    window.addEventListener('scroll', position, true);
    return () => {
      window.removeEventListener('resize', position);
      window.removeEventListener('scroll', position, true);
    };
  }, [open]);

  const close = () => {
    if (popup.current?.contains(document.activeElement))
      trigger.current?.focus();
    setOpen(false);
  };

  const exportMelody = async (format: ExportFormat) => {
    if (pending.current) return;
    pending.current = true;
    trigger.current?.focus();
    setBusy(true);
    setError('');
    setMessage('Preparing file…');
    try {
      await downloadMelody(
        melody,
        format,
        instruments[melody.timbre] ?? defaultEffects(melody.timbre),
        {
          optimizeTablature: optimizeFullTablature
            ? 'composition'
            : optimizeTablature,
        },
      );
      setMessage('Download started.');
      close();
    } catch (cause) {
      setMessage('');
      setError(
        cause instanceof MelodyExportError
          ? cause.message
          : 'Could not prepare the file. Try again.',
      );
    } finally {
      pending.current = false;
      setBusy(false);
    }
  };

  return (
    <Controls
      onBlur={event => {
        if (
          event.relatedTarget instanceof Node &&
          !event.currentTarget.contains(event.relatedTarget)
        )
          setOpen(false);
      }}
      onKeyDown={event => {
        if (!hasNotes && !hasTake) return;
        if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key))
          return;
        if (!open && event.key !== 'ArrowDown') return;
        event.preventDefault();
        if (!open) {
          setOpen(true);
          return;
        }
        const items = Array.from(
          popup.current?.querySelectorAll<HTMLButtonElement>(
            'button:enabled',
          ) ?? [],
        );
        if (!items.length) return;
        const current = items.indexOf(
          document.activeElement as HTMLButtonElement,
        );
        const next =
          event.key === 'Home'
            ? 0
            : event.key === 'End'
            ? items.length - 1
            : event.key === 'ArrowDown'
            ? (current + 1) % items.length
            : (Math.max(0, current) + items.length - 1) % items.length;
        items[next]?.focus();
      }}
    >
      <MelodyActionButton
        $withLabel={showLabel}
        ref={trigger}
        type="button"
        aria-label="Export melody"
        title={error || 'Export melody'}
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        disabled={!hasNotes && !hasTake}
        onClick={() => setOpen(!open)}
      >
        <MelodyActionIcon action="export" />
        {showLabel && 'Export'}
      </MelodyActionButton>
      {message && <Status role="status">{message}</Status>}
      {!open && error && <Status role="alert">{error}</Status>}
      {open && (
        <Options
          id={id}
          ref={popup}
          role="group"
          aria-label="Export formats"
          data-export-options=""
        >
          {busy && <Notice aria-hidden="true">{message}</Notice>}
          {error && <Notice role="alert">{error}</Notice>}
          {hasNotes &&
            formats.map(({ format, label }) => (
              <Option
                key={format}
                type="button"
                disabled={busy}
                onClick={() => void exportMelody(format)}
              >
                {label}
              </Option>
            ))}
          {hasTake && audioRecording && (
            <AudioOptions aria-label="Guitar / microphone recording">
              <strong>Guitar / microphone recording</strong>
              <Option
                type="button"
                disabled={busy}
                onClick={() => {
                  audioRecording.download();
                  close();
                }}
              >
                Download clean WAV
              </Option>
              <Option
                type="button"
                disabled={busy || audioRecording.exporting}
                onClick={() => {
                  trigger.current?.focus();
                  void audioRecording.downloadWithEffects();
                }}
              >
                Download WAV with effects
              </Option>
              {audioRecording.exporting && (
                <Notice role="status">Preparing WAV with effects…</Notice>
              )}
              {audioRecording.exportError && (
                <Notice role="alert">{audioRecording.exportError}</Notice>
              )}
            </AudioOptions>
          )}
        </Options>
      )}
    </Controls>
  );
};

const Controls = styled.div`
  display: flex;
  flex-shrink: 0;
`;

const Options = styled.div`
  position: fixed;
  z-index: 40;
  display: grid;
  width: min(${menuWidth}px, calc(100% - ${2 * inset}px));
  box-sizing: border-box;
  padding: 4px;
  overflow: auto;
  overscroll-behavior: contain;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.surface};
  box-shadow: 0 8px 28px ${p => p.theme.shadow};
`;

const Option = styled.button`
  width: 100%;
  min-height: 36px;
  padding: 6px 10px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: ${p => p.theme.text};
  font-size: 13px;
  text-align: left;
  cursor: pointer;

  &:enabled:hover,
  &:focus-visible {
    background: ${p => p.theme.borderLight};
    outline-offset: -2px;
  }
  &:disabled {
    opacity: 0.55;
    cursor: default;
  }
  @media (pointer: coarse) {
    min-height: 44px;
  }
`;

const AudioOptions = styled.section`
  padding-top: 4px;
  border-top: 1px solid ${p => p.theme.border};

  strong {
    display: block;
    padding: 6px 10px;
    color: ${p => p.theme.textSecondary};
    font-size: 12px;
  }
`;

const Notice = styled.div`
  padding: 6px 10px;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
`;

const Status = styled.span`
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
`;
