export type TunerCapture = {
  channels: number;
  deviceId: string;
  sampleRate: number;
  read(): Float32Array;
  setChannel(channel: number): void;
  dispose(): void;
};

export const openTunerCapture = async (
  deviceId: string,
  signal: AbortSignal,
  onEnded: () => void,
): Promise<TunerCapture> => {
  const Context = window.AudioContext || (window as any).webkitAudioContext;
  const context: AudioContext = new Context({ latencyHint: 'interactive' });
  let stream: MediaStream | undefined;
  let source: MediaStreamAudioSourceNode | undefined;
  let splitter: ChannelSplitterNode | undefined;
  let analyser: AnalyserNode | undefined;
  let mute: GainNode | undefined;
  let disposed = false;
  const cancelled = () => new DOMException('Tuner cancelled', 'AbortError');
  const dispose = () => {
    if (disposed) return;
    disposed = true;
    signal.removeEventListener('abort', dispose);
    stream?.getTracks().forEach(track => {
      track.removeEventListener('ended', onEnded);
      track.stop();
    });
    source?.disconnect();
    splitter?.disconnect();
    analyser?.disconnect();
    mute?.disconnect();
    void context.close().catch(() => {});
  };
  signal.addEventListener('abort', dispose, { once: true });
  try {
    if (signal.aborted) throw cancelled();
    // Resume in the initiating click, before the permission prompt resolves.
    const resumed = context.resume();
    const media = navigator.mediaDevices
      .getUserMedia({
        video: false,
        audio: {
          ...(deviceId ? { deviceId: { exact: deviceId } } : {}),
          channelCount: { ideal: 2 },
          echoCancellation: false,
          noiseSuppression: false,
          autoGainControl: false,
        },
      })
      .then(value => {
        if (disposed) {
          value.getTracks().forEach(track => track.stop());
          throw cancelled();
        }
        stream = value;
        return value;
      });
    const [input] = await Promise.all([media, resumed]);
    if (disposed) throw cancelled();
    const track = input.getAudioTracks()[0];
    if (!track || track.readyState === 'ended') throw new Error('Input ended');
    track.addEventListener('ended', onEnded);
    const settings = track.getSettings() as MediaTrackSettings & {
      channelCount?: number;
    };
    const channels = Math.max(1, Math.min(32, settings.channelCount ?? 1));
    source = context.createMediaStreamSource(input);
    splitter = context.createChannelSplitter(channels);
    analyser = context.createAnalyser();
    // Keep enough samples to measure low bass notes at high sample rates.
    analyser.fftSize = context.sampleRate > 96000 ? 16384 : 8192;
    mute = context.createGain();
    mute.gain.value = 0;
    source.connect(splitter);
    splitter.connect(analyser, 0);
    analyser.connect(mute);
    mute.connect(context.destination);
    const samples = new Float32Array(analyser.fftSize);
    return {
      channels,
      deviceId: settings.deviceId ?? deviceId,
      sampleRate: context.sampleRate,
      read() {
        analyser!.getFloatTimeDomainData(samples);
        return samples;
      },
      setChannel(channel) {
        if (!Number.isInteger(channel) || channel < 0 || channel >= channels)
          return;
        splitter!.disconnect();
        splitter!.connect(analyser!, channel);
      },
      dispose,
    };
  } catch (error) {
    dispose();
    throw error;
  }
};
