import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import {
  getNote,
  pitchNote,
  splitNote,
} from 'app/services/NotesService/noteUtils';
import type { JustNote, Note, Octave } from 'app/services/NotesService/types';

import { noteTuningCents } from './microtonal';
import { ScaleSelection, getScale } from './scales';

export const tonicForPitch = (pitch: number) =>
  chromaticNotes[((pitch % 12) + 12) % 12];

export const pitchForTonic = (tonic: JustNote, currentPitch: number) => {
  const index = chromaticNotes.indexOf(tonic);
  return [index - 12, index, index + 12]
    .filter(pitch => pitch >= -12 && pitch <= 12)
    .reduce((closest, pitch) =>
      Math.abs(pitch - currentPitch) < Math.abs(closest - currentPitch)
        ? pitch
        : closest,
    );
};

export type ScalePreviewNote = {
  key: JustNote;
  note: Note;
  cents: number;
};

export const getScalePreview = (
  selection: ScaleSelection,
  customScale?: JustNote[],
): ScalePreviewNote[] => {
  const root = tonicForPitch(selection.pitch);
  const degrees = getScale(selection.scale, selection.mode, customScale)
    .map(note => chromaticNotes.indexOf(note))
    .sort((a, b) => a - b);

  // Match the home row, including the octave shift from a signed transpose.
  const homeOctave = selection.octave + 1 + Math.floor(selection.pitch / 12);
  const crossesOctave =
    chromaticNotes.indexOf(root) + degrees[degrees.length - 1] >= 12;
  const octave = Math.max(
    0,
    Math.min(homeOctave, crossesOctave ? 7 : 8),
  ) as Octave;
  const tonic = getNote(root, octave);
  return degrees.map(degree => {
    const note = pitchNote(tonic, degree);
    return {
      key: splitNote(note)[0],
      note,
      cents: noteTuningCents(note, selection),
    };
  });
};
