import { shallowEqual, useSelector } from 'react-redux';

import { selectMelodies } from 'app/services/MelodiesService';
import { getNote, selectNotes, splitNote } from 'app/services/NotesService';
import { scales } from 'app/services/SettingsService';

import { PianoKey } from './PianoKey';

export const PianoOctave = ({ octave }) => {
  const soundingNotes = useSelector(state => selectNotes(state).soundingNotes);
  const highlightedNotes = useSelector(
    state => selectNotes(state).highlightedNotes,
  );
  const playbackNotes = useSelector(state => {
    const { melody } = selectNotes(state);
    return selectMelodies(state).soundingNoteIndices.map(
      index => melody.notes[index]?.note,
    );
  }, shallowEqual);
  const highlightedJustNotes = highlightedNotes.map(note => splitNote(note)[0]);

  return (
    <>
      {scales.chromatic.intervals.map(justNote => {
        const note = getNote(justNote, octave);
        const isPressed =
          soundingNotes.includes(note) || playbackNotes.includes(note);

        return (
          <PianoKey
            key={`piano-note-${note}`}
            note={note}
            isPressed={isPressed}
            isHighlighted={highlightedJustNotes.includes(splitNote(note)[0])}
          />
        );
      })}
    </>
  );
};
