import { createSelector } from '@reduxjs/toolkit';

import { RootState } from 'app/services/types';

import { initialState } from '.';

const selectSlice = (state: RootState) => state.keyboard || initialState;

export const selectKeyboard = createSelector([selectSlice], state => state);

export const selectPressedKeys = createSelector(
  [selectSlice],
  notes => notes.pressedKeys,
);
