import type { Note } from 'app/services/NotesService/types';

import { getKeyboardNote } from './noteByKey';
import type { KeyCode } from './types';

export type StudioScaleKey = { code: KeyCode; note: Note };
export type StudioScaleCue = (
  | { phase: 'select'; picked: number }
  | { phase: 'morph' }
  | { phase: 'play'; octaves: number; key?: StudioScaleKey }
) & { hold: number };

export const openingScaleCue: StudioScaleCue = {
  phase: 'select',
  picked: 0,
  hold: 260,
};

export const studioKeyMorphMs = 520;
export const studioKeyStaggerMs = 28;

export const getStudioScaleDemo = (
  layout: Parameters<typeof getKeyboardNote>[1],
) => {
  const size = layout.scaleNotes.length;
  // The chromatic layout has fewer than four octaves.
  const count = Math.min(4, Math.ceil(layout.applicature.length / size));
  const octaves = Array.from({ length: count }, (_, index) =>
    layout.applicature.slice(index * size, (index + 1) * size).flatMap(code => {
      const note = getKeyboardNote(code, layout);
      return note ? [{ code, note }] : [];
    }),
  );
  const piano = octaves[0];
  const cues: StudioScaleCue[] = [
    openingScaleCue,
    ...piano.map(
      (_, index): StudioScaleCue => ({
        phase: 'select',
        picked: index + 1,
        hold: index === piano.length - 1 ? 320 : 105,
      }),
    ),
    {
      phase: 'morph',
      hold: studioKeyMorphMs + (piano.length - 1) * studioKeyStaggerMs + 40,
    },
  ];
  octaves.forEach((keys, index) => {
    const count = index + 1;
    cues.push({ phase: 'play', octaves: count, hold: index ? 220 : 300 });
    keys.forEach(key =>
      cues.push({ phase: 'play', octaves: count, key, hold: 215 }),
    );
    cues.push({ phase: 'play', octaves: count, hold: 125 });
  });
  return { octaves, cues };
};
